#!/usr/bin/env bash
# Question 6: One worker takes no Pods. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

[[ "$CKA_NODE" == "${Q6_NODE}" ]] || exit 0

case "${Q6_FAULT}" in
  cordoned) ;;
  taint-noschedule) ;;
  taint-noexecute) ;;
  label-removed) ;;
  max-pods)
    sed -i '/^maxPods:/d' /var/lib/kubelet/config.yaml
    echo 'maxPods: 2' >> /var/lib/kubelet/config.yaml
    grep -qx 'maxPods: 2' /var/lib/kubelet/config.yaml
    systemctl restart kubelet
    ;;
esac
